        default:
            if strings.HasPrefix(args[i], "--") {
                return "", "", nil, fmt.Errorf("unknown flag: %s", args[i])
            }
            configs = append(configs, args[i])
        }
    }
    if len(configs) != 2 {
        return "", "", nil, fmt.Errorf("usage: mlpipe diff <config1.json> <config2.json> [--param key=value ...]")
    }
    return configs[0], configs[1], overrides, nil
}
